parameters.command:
ls -lh registry-evidence/ && echo "---" && python3 -c "
import json, os
for f in sorted(os.listdir('registry-evidence')):
    raw = open(f'registry-evidence/{f}').read()
    try:
        d = json.loads(raw)
        print(f'{f}: valid JSON, top-level keys={list(d.keys())[:6]}')
    except Exception as e:
        print(f'{f}: {e}')
"

